```typescript
import { pgTable, text, integer, timestamp } from 'drizzle-orm/pg-core';

export const analyticsTable = pgTable('analytics', {
  id: text('id').primaryKey(),
  eventType: text('event_type').notNull(),
  userId: text('user_id').notNull(),
  metadata: text('metadata'), // JSON string stored as text for simplicity
  createdAt: timestamp('created_at').defaultNow().notNull(),
});
```

Filename: `src/lib/validations.ts`
```typescript
import { z } from 'zod';

// Flag: Injection defense. Schema validation before DB query.
export const AnalyticsQuerySchema = z.object({
  eventType: z.enum(['page_view', 'click', 'purchase']).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(10),
  offset: z.coerce.number().int().min(0).default(0),
});

export type AnalyticsQuery = z.infer<typeof AnalyticsQuerySchema>;
```

Filename: `src/app/api/analytics/route.ts`
```typescript
import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { analyticsTable } from '@/lib/schema';
import { AnalyticsQuerySchema } from '@/lib/validations';
import { eq, desc, like } from 'drizzle-orm';

// Flag: Server-side proxy. Client calls /api/analytics, endpoint calls DB.
export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const rawParams = Object.fromEntries(searchParams.entries());

    // Validate input schema
    const params = AnalyticsQuerySchema.parse(rawParams);

    // Flag: Injection defense. Drizzle uses bound parameters for values.
    // Identifiers (table/column) are literals in the schema definition.
    const query = db.select()
      .from(analyticsTable)
      .where(
        params.eventType 
          ? eq(analyticsTable.eventType, params.eventType) 
          : undefined
      )
      .orderBy(desc(analyticsTable.createdAt))
      .limit(params.limit)
      .offset(params.offset);

    const data = await query;

    return NextResponse.json({
      success: true,
      data,
      meta: {
        limit: params.limit,
        offset: params.offset,
      },
    });
  } catch (error) {
    if (error instanceof Error && error.name === 'ZodError') {
      return NextResponse.json(
        { success: false, error: 'Invalid query parameters' },
        { status: 400 }
      );
    }
    console.error('Analytics query failed:', error);
    return NextResponse.json(
      { success: false, error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

Filename: `src/app/dashboard/page.tsx`
```typescript
'use client';

import { useEffect, useState } from 'react';

interface AnalyticsData {
  id: string;
  event_type: string;
  user_id: string;
  metadata: string | null;
  created_at: string;
}

export default function DashboardWidget() {
  const [data, setData] = useState<AnalyticsData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAnalytics() {
      try {
        const response = await fetch('/api/analytics?limit=5');
        if (!response.ok) {
          throw new Error('Failed to fetch analytics');
        }
        const json = await response.json();
        if (json.success) {
          setData(json.data);
        } else {
          throw new Error(json.error || 'Unknown error');
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An error occurred');
      } finally {
        setLoading(false);
      }
    }

    fetchAnalytics();
  }, []);

  if (loading) return <div className="p-4">Loading analytics...</div>;
  if (error) return <div className="p-4 text-red-500">Error: {error}</div>;

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-xl font-bold mb-4">Recent Analytics</h2>
      <ul className="space-y-2">
        {data.map((item) => (
          <li key={item.id} className="p-2 bg-gray-50 rounded">
            <div className="flex justify-between">
              <span className="font-medium">{item.event_type}</span>
              <span className="text-sm text-gray-500">
                {new Date(item.created_at).toLocaleDateString()}
              </span>
            </div>
            <div className="text-sm text-gray-600">
              User: {item.user_id}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

